<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {ElMessageBox,ElMessage} from 'element-plus'
import {api,post,formatDate} from '../api'
import type {Project} from '../project'
type Material={id:string;filename:string;purpose:string;size:number;use_in_workflow:boolean;created_at:string}
const projects=ref<Project[]>([]),selected=ref<Project|null>(null),materials=ref<Material[]>([]),error=ref(''),busy=ref(false),purpose=ref('project'),query=ref(''),group=ref('all'),preview=ref<any>(null),rejected=ref<{filename:string;error:string}[]>([])
const formOpen=ref(false),editing=ref(''),name=ref(''),code=ref(''),start=ref(''),cutoff=ref(''),basis=ref(''),accessCode=ref(''),codeOpen=ref(false)
const purposeNames:Record<string,string>={project:'项目原始材料',reference:'参考材料',instruction:'流程说明'}
const visible=computed(()=>materials.value.filter(m=>(group.value==='all'||m.purpose===group.value)&&m.filename.includes(query.value)))
async function load(){projects.value=await api('/admin/projects');if(selected.value)selected.value=projects.value.find(p=>p.id===selected.value!.id)||null}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function open(p:Project){selected.value=p;query.value='';group.value='all';rejected.value=[];await run(async()=>{materials.value=await api(`/admin/projects/${p.id}/materials`)})}
function edit(p?:Project){editing.value=p?.id||'';name.value=p?.name||'';code.value=p?.code||'';start.value=p?.search_boundary?.project_start_date||'';cutoff.value=p?.search_boundary?.review_cutoff||'';basis.value=p?.search_boundary?.cutoff_basis||'';formOpen.value=true}
async function save(){await run(async()=>{if((start.value||cutoff.value||basis.value)&&!(start.value&&cutoff.value&&basis.value.trim()))throw new Error('请完整填写评测日期范围及日期依据');const body={name:name.value,code:code.value,search_boundary:start.value?{project_start_date:start.value,review_cutoff:cutoff.value,cutoff_basis:basis.value}:null};const result=await api<Project&{access_code?:string}>('/admin/projects'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify(body)});formOpen.value=false;await load();if(result.access_code){accessCode.value=result.access_code;codeOpen.value=true}})}
async function rotate(){if(!selected.value)return;try{await ElMessageBox.confirm('更新后，已加入该项目的用户需要输入新安全码才能继续访问。','更新项目安全码',{confirmButtonText:'更新安全码',cancelButtonText:'取消'})}catch{return}await run(async()=>{const result=await post<{access_code:string}>(`/admin/projects/${selected.value!.id}/access-code`);accessCode.value=result.access_code;codeOpen.value=true})}
async function copyCode(){try{await navigator.clipboard.writeText(accessCode.value);ElMessage.success('安全码已复制')}catch{ElMessage.error('请手动复制安全码')}}
async function upload(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.length||!selected.value)return;const data=new FormData();Array.from(input.files).forEach(f=>data.append('files',f,(f as any).webkitRelativePath||f.name));data.append('purpose',purpose.value);await run(async()=>{const r=await api<{accepted_count:number;rejected:{filename:string;error:string}[]}>(`/admin/projects/${selected.value!.id}/materials`,{method:'POST',body:data});rejected.value=r.rejected;materials.value=await api(`/admin/projects/${selected.value!.id}/materials`);await load();ElMessage.success(`已导入 ${r.accepted_count} 份材料`)});input.value=''}
async function toggle(m:Material,value:unknown){await run(async()=>{await api(`/admin/projects/${selected.value!.id}/materials/${m.id}`,{method:'PATCH',body:JSON.stringify({use_in_workflow:!!value})});m.use_in_workflow=!!value})}
async function deleteProject(){
 const p=selected.value;if(!p)return
 try{await ElMessageBox.prompt(`将删除“${p.name}”的全部材料、工单、工作流和报告，并撤销用户访问权限。请输入项目名称确认。`,'删除项目',{confirmButtonText:'删除项目',cancelButtonText:'取消',inputValidator:v=>v===p.name||'请输入完整项目名称',type:'warning'})}catch{return}
 await run(async()=>{await api('/admin/projects/'+p.id,{method:'DELETE'});selected.value=null;materials.value=[];await load();ElMessage.success('项目已删除')})
}
async function deleteMaterial(m:Material){
 if(!selected.value)return
 try{await ElMessageBox.confirm(`删除材料“${m.filename}”及其存储文件？`,'删除材料',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'})}catch{return}
 await run(async()=>{await api(`/admin/projects/${selected.value!.id}/materials/${m.id}`,{method:'DELETE'});materials.value=materials.value.filter(x=>x.id!==m.id);await load();ElMessage.success('材料已删除')})
}
onMounted(()=>run(load))
</script>
<template><div class="content-page project-page"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="!selected"><div class="section-heading"><h2>项目材料库</h2><el-button type="primary" @click="edit()">新建项目</el-button></div><div class="project-grid"><button v-for="p in projects" :key="p.id" class="project-folder" @click="open(p)"><span class="folder-tab">{{p.code}}</span><div class="folder-body"><svg width="32" height="27" viewBox="0 0 32 27" fill="none" aria-hidden="true"><path d="M1 6V3a2 2 0 012-2h9l4 5h13a2 2 0 012 2v16a2 2 0 01-2 2H3a2 2 0 01-2-2V6Z" stroke="currentColor" stroke-width="1.5"/><path d="M1 9h30" stroke="currentColor"/></svg><h3>{{p.name}}</h3><div class="folder-counts"><span>{{p.material_count}} 份材料</span><span>{{p.report_count}} 份报告</span><b>打开 →</b></div></div></button></div><div v-if="!projects.length" class="panel empty-project">尚未创建项目</div></template><template v-else><div class="project-toolbar"><div><el-button text @click="selected=null">← 全部项目</el-button><h2 class="project-heading">{{selected.name}}</h2></div><div class="toolbar-actions"><el-button @click="edit(selected)">项目设置</el-button><el-button @click="rotate">更新安全码</el-button><el-button type="danger" plain :disabled="busy" @click="deleteProject">删除项目</el-button></div></div><div class="panel material-controls"><el-select v-model="purpose" aria-label="上传材料用途"><el-option v-for="(label,value) in purposeNames" :key="value" :value="value" :label="label"/></el-select><label class="file-control" :class="{disabled:busy}">上传文件 / ZIP<input type="file" multiple accept=".txt,.md,.pdf,.docx,.xlsx,.zip" :disabled="busy" @change="upload"/></label><label class="file-control" :class="{disabled:busy}">上传文件夹<input type="file" multiple webkitdirectory :disabled="busy" @change="upload"/></label></div><el-alert v-for="r in rejected" :key="r.filename" :title="r.filename+'：'+r.error" type="warning" :closable="false"/><div class="material-filter"><el-radio-group v-model="group"><el-radio-button value="all">全部材料</el-radio-button><el-radio-button v-for="(label,value) in purposeNames" :key="value" :value="value">{{label}}</el-radio-button></el-radio-group><el-input v-model="query" aria-label="查找项目材料" placeholder="查找文件" clearable/></div><div class="panel"><el-table :data="visible" empty-text="该项目暂无材料"><el-table-column label="材料" min-width="260"><template #default="{row}"><button class="material-name" @click="run(async()=>{preview=await api('/admin/materials/'+row.id)})">{{row.filename}}</button></template></el-table-column><el-table-column label="用途" width="130"><template #default="{row}">{{purposeNames[row.purpose]}}</template></el-table-column><el-table-column label="默认用于评测" width="140"><template #default="{row}"><el-checkbox :model-value="row.use_in_workflow" :disabled="busy||row.purpose!=='project'" :aria-label="row.filename+'用于评测'" @change="(v:any)=>toggle(row,v)"/></template></el-table-column><el-table-column label="大小" width="100"><template #default="{row}">{{(row.size/1024/1024).toFixed(2)}} MB</template></el-table-column><el-table-column label="操作" width="155"><template #default="{row}"><a :href="'/api/admin/materials/'+row.id+'/download'" class="text-link">下载</a><el-button type="danger" text :disabled="busy" @click="deleteMaterial(row)" :aria-label="'删除材料 '+row.filename">删除</el-button></template></el-table-column></el-table></div></template><el-dialog v-model="formOpen" :title="editing?'项目设置':'新建项目'" width="min(580px,94vw)"><el-form label-position="top" @submit.prevent="save"><el-form-item label="项目名称"><el-input v-model="name" maxlength="200"/></el-form-item><el-form-item label="项目编号"><el-input v-model="code" maxlength="100" :disabled="!!editing"/></el-form-item><div class="date-pair"><el-form-item label="项目启动日期"><input type="date" v-model="start"/></el-form-item><el-form-item label="本次评价证据截止日"><input type="date" v-model="cutoff"/></el-form-item></div><el-form-item label="证据截止日依据"><el-input v-model="basis" type="textarea" :rows="3" maxlength="1000"/></el-form-item><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="dialog-actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="!name.trim()||!code.trim()">保存项目</el-button></div></el-form></el-dialog><el-dialog v-model="codeOpen" title="项目安全码" width="min(580px,94vw)"><div class="access-code">{{accessCode}}</div><div class="dialog-actions"><el-button type="primary" @click="copyCode">复制安全码</el-button></div></el-dialog><el-dialog :model-value="!!preview" @close="preview=null" :title="preview?.filename" width="min(980px,94vw)"><pre class="material-text">{{preview?.text}}</pre></el-dialog></div></template>
